impl EventPayload{fn validate(&self,m:&EventMetadata)->Result<(),EventError>{m.validate()?;let instrument=matches!(self,Self::Trade(_)|Self::TopOfBook(_)|Self::BookSnapshot(_)|Self::BookDelta(_)|Self::InstrumentDefinition(_)|Self::Funding(_)|Self::OpenInterest(_)|Self::Liquidation(_)|Self::MarkIndex(_)|Self::OptionTicker(_));if instrument&&(m.instrument_id.is_none()||m.venue.is_none()){return Err(EventError::Metadata)}match self{Self::Trade(v)if v.trade_id.is_empty()||v.quantity.value().is_zero()=>Err(EventError::Payload),Self::TopOfBook(v)if v.bid_price>=v.ask_price=>Err(EventError::Payload),Self::BookSnapshot(v)=>{book(&v.bids,&v.asks,false)?;if m.snapshot_kind!=SnapshotKind::Snapshot||m.sequence_number!=Some(v.last_sequence){return Err(EventError::SequenceMismatch)}Ok(())},Self::BookDelta(v)=>{book(&v.bids,&v.asks,true)?;if v.first_sequence>v.last_sequence||m.snapshot_kind!=SnapshotKind::Delta||m.sequence_number!=Some(v.last_sequence){return Err(EventError::SequenceMismatch)}Ok(())},Self::InstrumentDefinition(v)if m.instrument_id.as_ref()!=Some(v.id())=>Err(EventError::Metadata),Self::Liquidation(v)if v.quantity.value().is_zero()=>Err(EventError::Payload),Self::OptionTicker(v)if v.mark_iv.value().is_negative()||v.bid_iv.zip(v.ask_iv).is_some_and(|(a,b)|a>b)=>Err(EventError::Payload),Self::ChainBlock(v)if v.chain.is_empty()||v.hash.is_empty()=>Err(EventError::Payload),Self::StructuredEvent{assets,source_reference,..}if assets.is_empty()||source_reference.is_empty()=>Err(EventError::Payload),Self::DataQuality{code,detail}if code.is_empty()||detail.is_empty()=>Err(EventError::Payload),_=>Ok(())}}}
