impl EventEnvelope{pub fn new(metadata:EventMetadata,payload:EventPayload)->Result<Self,EventError>{payload.validate(&metadata)?;let id=calculate_id(&metadata,&payload)?;Ok(Self{id,metadata,payload})}pub const fn id(&self)->EventId{self.id}pub fn metadata(&self)->&EventMetadata{&self.metadata}pub fn payload(&self)->&EventPayload{&self.payload}pub fn verify(&self)->Result<(),EventError>{if calculate_id(&self.metadata,&self.payload)?==self.id{Ok(())}else{Err(EventError::IdentityMismatch)}}}
fn calculate_id(m:&EventMetadata,p:&EventPayload)->Result<EventId,EventError>{let mut bytes=Vec::new();bytes.extend_from_slice(EVENT_DOMAIN);put(&mut bytes,&serde_json::to_vec(m).map_err(|_|EventError::Payload)?)?;put(&mut bytes,&canonical_payload(p)? )?;Ok(EventId(*blake3::hash(&bytes).as_bytes()))}
fn canonical_payload(p:&EventPayload)->Result<Vec<u8>,EventError>{let mut b=Vec::new();match p{EventPayload::Trade(v)=>{s(&mut b,&v.trade_id);d(&mut b,v.price.value());d(&mut b,v.quantity.value());b.push(v.side as u8)},EventPayload::TopOfBook(v)=>for x in[v.bid_price.value(),v.bid_quantity.value(),v.ask_price.value(),v.ask_quantity.value()]{d(&mut b,x)},EventPayload::BookSnapshot(v)=>{levels(&mut b,&v.bids);levels(&mut b,&v.asks);b.extend_from_slice(&v.last_sequence.to_be_bytes())},EventPayload::BookDelta(v)=>{levels(&mut b,&v.bids);levels(&mut b,&v.asks);b.extend_from_slice(&v.first_sequence.to_be_bytes());b.extend_from_slice(&v.last_sequence.to_be_bytes())},EventPayload::InstrumentDefinition(v)=>s(&mut b,&v.id().to_string()),EventPayload::Funding(v)=>d(&mut b,v.current_rate.value()),EventPayload::OpenInterest(v)=>d(&mut b,v.contracts.value()),EventPayload::Liquidation(v)=>{d(&mut b,v.price.value());d(&mut b,v.quantity.value());s(&mut b,&v.completeness)},EventPayload::MarkIndex(v)=>{d(&mut b,v.mark_price.value());d(&mut b,v.index_price.value())},EventPayload::OptionTicker(v)=>d(&mut b,v.mark_iv.value()),EventPayload::ChainBlock(v)=>{s(&mut b,&v.chain);b.extend_from_slice(&v.height.to_be_bytes());s(&mut b,&v.hash);s(&mut b,&v.parent_hash)},EventPayload::StructuredEvent{event_type,assets,source_reference}=>{s(&mut b,event_type);for a in assets{s(&mut b,a)}s(&mut b,source_reference)},EventPayload::DataQuality{code,detail}=>{s(&mut b,code);s(&mut b,detail)}}Ok(b)}
fn put(b:&mut Vec<u8>,v:&[u8])->Result<(),EventError>{let n=u32::try_from(v.len()).map_err(|_|EventError::Payload)?;b.extend_from_slice(&n.to_be_bytes());b.extend_from_slice(v);Ok(())}fn s(b:&mut Vec<u8>,v:&str){b.extend_from_slice(&(v.len()as u32).to_be_bytes());b.extend_from_slice(v.as_bytes())}fn d(b:&mut Vec<u8>,v:FixedDecimal){s(b,&v.to_string())}fn levels(b:&mut Vec<u8>,v:&[BookLevel]){b.extend_from_slice(&(v.len()as u32).to_be_bytes());for l in v{d(b,l.price.value());d(b,l.quantity.value())}}
fn book(bids:&[BookLevel],asks:&[BookLevel],allow_zero:bool)->Result<(),EventError>{if bids.len()+asks.len()>MAX_LEVELS||(!allow_zero&&bids.iter().chain(asks).any(|l|l.quantity.value().is_zero()))||!bids.windows(2).all(|w|w[0].price>w[1].price)||!asks.windows(2).all(|w|w[0].price<w[1].price)||bids.first().zip(asks.first()).is_some_and(|(b,a)|b.price>=a.price){Err(EventError::Payload)}else{Ok(())}}
